import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000005;
    static final int MODULUS = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_value = sc.nextInt();
        int k_value = sc.nextInt();

        if (k_value == 0) {
            long prod = 1;
            for (int i = 1; i < p_value; ++i) {
                prod = (prod * p_value) % MODULUS;
            }
            System.out.println(prod);
            sc.close();
            return;
        }

        int[] sequence = new int[p_value];
        boolean[] visited_nodes = new boolean[p_value];

        for (int i = 1; i < p_value; ++i) {
            sequence[i] = (int)((long)k_value * i % p_value);
        }

        long answer = 1;
        for (int start = 0; start < p_value; ++start) {
            if (!visited_nodes[start]) {
                int length = 0;
                int current = start;
                long tmp_product = 1;
                while (!visited_nodes[current]) {
                    visited_nodes[current] = true;
                    current = sequence[current];
                    length++;
                    tmp_product = (tmp_product * k_value) % p_value;
                }
                if (length == 1) {
                    int factor = (k_value == 1) ? p_value : 1;
                    answer = (answer * factor) % MODULUS;
                } else {
                    assert tmp_product == 1;
                    answer = (answer * p_value) % MODULUS;
                }
            }
        }
        System.out.println(answer);
        sc.close();
    }
}

